## 快速启动空间站悬疑检查清单

以下是我们为您的宇宙谋杀悬疑派对准备星际阴谋的方法：

- **布置太空场景：** 用未来主义照明、金属装饰和高科技道具改造您的空间
- **创建科幻角色：** 设计与您朋友个性相匹配且带有太空时代风格的角色
- **开发未来主义线索：** 使用计算机日志、生物扫描报告、通信记录和外星文物
- **规划太空时间线：** 空间站到达程序、船员简报、戏剧性事件、调查阶段
- **设计太空服装：** 连体衣、工具带、通信设备和未来主义配件
- **准备太空食物：** 冷冻干燥零食、金属包装和未来主义饮料呈现
- **建立宇宙冲突：** 包括资源短缺、外星遭遇、企业阴谋和生存压力
